using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using CashBoard.Api.Data;
using CashBoard.Api.Models;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
var builder = WebApplication.CreateBuilder(args); var jwt = builder.Configuration.GetSection("Jwt"); var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt["Key"]!));
builder.Services.AddDbContext<AppDbContext>(o => o.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection"))); builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new() { ValidateIssuer = true, ValidateAudience = true, ValidateLifetime = true, ValidateIssuerSigningKey = true, ValidIssuer = jwt["Issuer"], ValidAudience = jwt["Audience"], IssuerSigningKey = key }); builder.Services.AddAuthorization(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.WithOrigins("http://localhost:4200").AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build(); app.UseSwagger(); app.UseSwaggerUI(); app.UseCors(); app.UseAuthentication(); app.UseAuthorization();
app.MapPost("/api/auth/login", async (LoginRequest r, AppDbContext db) => { var u = await db.Users.FirstOrDefaultAsync(x => x.Email == r.Email); if (u is null || !BCrypt.Net.BCrypt.Verify(r.Password, u.PasswordHash)) return Results.Unauthorized(); var claims = new[] { new Claim(JwtRegisteredClaimNames.Sub, u.Id.ToString()), new Claim("familyId", u.FamilyId.ToString()), new Claim(ClaimTypes.Role, u.Role.ToString()) }; var token = new JwtSecurityToken(jwt["Issuer"], jwt["Audience"], claims, expires: DateTime.UtcNow.AddHours(8), signingCredentials: new SigningCredentials(key, SecurityAlgorithms.HmacSha256)); return Results.Ok(new { token = new JwtSecurityTokenHandler().WriteToken(token), user = new { u.Id, u.Name, u.Email, u.Role } }); });
app.MapGet("/api/dashboard/summary", async (AppDbContext db) => { var now = DateTime.UtcNow; var q = db.Transactions.Where(x => x.Date.Year == now.Year && x.Date.Month == now.Month); var income = await q.Where(x => x.Type == TransactionType.Income).SumAsync(x => (decimal?)x.Amount) ?? 0; var expenses = await q.Where(x => x.Type == TransactionType.Expense).SumAsync(x => (decimal?)x.Amount) ?? 0; return Results.Ok(new { income, expenses, balance = income - expenses, saved = await db.SavingsGoals.SumAsync(x => (decimal?)x.CurrentAmount) ?? 0, pendingDebt = await db.Debts.SumAsync(x => (decimal?)(x.TotalAmount - x.PaidAmount)) ?? 0 }); }).RequireAuthorization();
app.MapGet("/api/transactions", (AppDbContext db) => db.Transactions.Include(x => x.Category).OrderByDescending(x => x.Date).ToListAsync()).RequireAuthorization(); app.MapPost("/api/transactions", async (Transaction tx, AppDbContext db) => { db.Add(tx); await db.SaveChangesAsync(); return Results.Created($"/api/transactions/{tx.Id}", tx); }).RequireAuthorization(); app.MapGet("/api/budgets/current", (AppDbContext db) => db.Budgets.Include(x => x.Category).ToListAsync()).RequireAuthorization(); app.MapGet("/api/savings-goals", (AppDbContext db) => db.SavingsGoals.ToListAsync()).RequireAuthorization(); app.MapPost("/api/savings-goals", async (SavingsGoal x, AppDbContext db) => { db.Add(x); await db.SaveChangesAsync(); return Results.Created($"/api/savings-goals/{x.Id}", x); }).RequireAuthorization(); app.MapGet("/api/debts", (AppDbContext db) => db.Debts.ToListAsync()).RequireAuthorization(); app.MapGet("/health", () => Results.Ok(new { status = "healthy" })); app.Run(); record LoginRequest(string Email, string Password);
